// Step 1: Validate Task Mutation Parameters
const input = $input.first().json;

const userId = input.user_id;
const taskId = input.task_id;
const operation = input.operation || 'update';
const newStatus = input.new_status || input.status;
const title = input.title;
const priority = input.priority;
const dueDate = input.due_date;
const dueTime = input.due_time;
const timeKnown = input.time_known !== undefined ? Boolean(input.time_known) : undefined;

return [{
  json: {
    ...input,
    user_id: userId,
    task_id: taskId,
    operation: operation,
    target_status: newStatus,
    new_title: title,
    new_priority: priority,
    new_due_date: dueDate,
    new_due_time: dueTime,
    new_time_known: timeKnown
  }
}];

const req = $('Prepare Task Mutation').first().json;
const trRaw = $input.first().json.transition_res;

return [{
  json: {
    ok: true,
    status: 'completed',
    correlation_id: req.correlation_id,
    data: {
      task_id: req.task_id,
      operation: req.operation,
      new_status: req.target_status || 'updated'
    }
  }
}];
